import json
URL="https://raw.githubusercontent.com/denisseram/dataset-snapshots/3731e02e38c75e5d70ae92bf3596a69951866c2d/ubuntu.csv"
DF=["created","release","eol","eol-server","eol-esm","eol-legacy"]
def data(): return {"url":URL,"type":"csv-time","dateFields":DF}
def has(f): return {"type":"filter","field":f,"inRange":[-1e12,1e12]}
def x(f):
    return {"field":f,"type":"temporal","relative":{"anchor":{"field":"release"},"unit":"year","label":"the release"},
            "domain":{"interval":["-1 year","16 years"]},"axis":"bottom"}
PH=[("Development (created → release)","created","release","#9e9e9e",[]),
    ("Standard support","release","eol","#4e79a7",["eol"]),
    ("ESM","eol","eol-esm","#f28e2b",["eol-esm"]),
    ("Extended server support","eol","eol-server","#59a14f",["eol-server"]),
    ("Legacy add-on","eol-esm","eol-legacy","#b07aa1",["eol-esm","eol-legacy"])]
def view(title, lts, h, legend):
    sel={"type":"filter","field":"version","include":"LTS","not": not lts}
    tracks=[]
    for lab,a,b,c,req in PH:
        tracks.append({"mark":"bar","x":x(a),"xe":x(b),
            "dataTransform":[sel]+[has(f) for f in req],
            "color":{"value":c},"size":{"value":9 if lts else 7},
            "style":{"legendLabel":lab} if legend else {}})
    for f,c in [("created","black"),("release","black")]:
        tracks.append({"mark":"point","x":x(f),"dataTransform":[sel],
            "color":{"value":"white" if f=="created" else "black"},"stroke":{"value":"black"},"strokeWidth":{"value":1},
            "size":{"value":3},"style":{"legendLabel":("● release (0)" if f=="release" else "○ created")} if legend else {}})
    return {"tracks":[{"title":title,"alignment":"overlay","data":data(),
        "row":{"field":"version","type":"nominal","legend":True},
        "x":x("release"),"tracks":tracks,"width":1150,"height":h}]}
